const menu=document.querySelector('.menu-button');
menu?.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(expanded));document.querySelector('#navigation').classList.toggle('open',expanded)});
document.querySelectorAll('#navigation a').forEach(a=>a.addEventListener('click',()=>{menu?.setAttribute('aria-expanded','false');document.querySelector('#navigation').classList.remove('open')}));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('#publication-list .pub-row').forEach(row=>{row.hidden=filter!=='All'&&!row.dataset.tags.split('|').includes(filter);if(!row.hidden)count++});document.querySelector('.result-count').textContent=`${count} publication${count===1?'':'s'}`;}));
let citations;
document.querySelectorAll('.copy-citation').forEach(button=>button.addEventListener('click',async()=>{try{citations??=await fetch('/citations.json').then(r=>{if(!r.ok)throw Error('Fetch failed');return r.json()});await navigator.clipboard.writeText(citations[button.dataset.id]);button.textContent='Copied';setTimeout(()=>button.textContent='Copy citation',1800)}catch{button.textContent='Use publisher citation';button.setAttribute('title','Open the Publisher / DOI link to copy the citation.')}}));
